using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using MapSharedProps.EditorTools;
public static class Rope102Checks {
 static string Root=>Path.GetFullPath(Path.Combine(Application.dataPath,".."));static void Check(bool v,string s){if(!v)throw new Exception(s);}
 static Dictionary<string,GameObject> Build(string stage){string folder="Assets/Imported102-"+stage;if(stage=="before"&&AssetDatabase.IsValidFolder(folder)){var cached=new Dictionary<string,GameObject>();foreach(var file in Directory.GetFiles(Path.Combine(Root,folder),"small-*.prefab"))cached.Add(Path.GetFileNameWithoutExtension(file).Substring(6),AssetDatabase.LoadAssetAtPath<GameObject>(folder+"/"+Path.GetFileName(file)));Check(cached.Count==43,"43 baseline prefabs");return cached;}Check(!AssetDatabase.IsValidFolder(folder),"Fresh test output required");AssetDatabase.CreateFolder("Assets",folder.Substring(7));var root=new GameObject("Coiled rope "+stage);var p=new Dictionary<string,GameObject>();Check(SmallPropsV1.Build(Path.Combine(Root,"Input102-"+stage),folder,root.transform,Shader.Find("MapSharedProps/Lit"),p)==1&&p.Count==43,"43 prefabs/one placement");if(stage=="after"){var prototype=p["coiledrope"].GetComponent<MeshFilter>().sharedMesh;var placed=root.GetComponentsInChildren<MeshFilter>().Single().sharedMesh;Check(prototype.uv.SequenceEqual(placed.uv),"grounded atlas UV and vertical flip exact");Check(placed.bounds.min.y>=-.003f,"ground contact");}PrefabUtility.SaveAsPrefabAsset(root,"Assets/rope102-"+stage+".prefab");UnityEngine.Object.DestroyImmediate(root);AssetDatabase.SaveAssets();return p;}
 public static void Run(){int exit=0;string output=Path.Combine(Root,"Evidence102Import");Directory.CreateDirectory(output);try{
 EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var before=Build("before");var after=Build("after");
 Check(before["coiledrope"].GetComponentsInChildren<Collider>(true).Length==0&&after["coiledrope"].GetComponentsInChildren<Collider>(true).Length==0,"nonblocking tools preserved");
 foreach(var id in before.Keys.Where(x=>x!="coiledrope"))Check(before[id].GetComponent<MeshFilter>().sharedMesh==after[id].GetComponent<MeshFilter>().sharedMesh,"unrelated mesh exact "+id);
 var placedMesh=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/rope102-after.prefab").GetComponentsInChildren<MeshFilter>().Single().sharedMesh;Check(placedMesh.uv.SequenceEqual(after["coiledrope"].GetComponent<MeshFilter>().sharedMesh.uv),"saved grounded fibre UV exact");var m=after["coiledrope"].GetComponent<MeshFilter>().sharedMesh;Check(m.vertexCount/3<=1300,"tool triangle budget");Check(m.vertices.All(v=>float.IsFinite(v.x)&&float.IsFinite(v.y)&&float.IsFinite(v.z)),"finite geometry");
 var ma=after["coiledrope"].GetComponent<Renderer>().sharedMaterial;Check(ma.shader.name=="MapSharedProps/FibreProp"&&ma.GetFloat("_FibreKind")==1,"rope material only");Check(after["tiedsack"].GetComponent<Renderer>().sharedMaterial.GetFloat("_FibreKind")==0,"cloth remains separate");Check(!ma.GetTexture("_BaseMap")||ma.GetTexture("_BaseMap")==Texture2D.whiteTexture,"no image texture allocated; unused map may serialize as null");
 Check(after["coiledrope"].GetComponentsInChildren<Light>(true).Length==0,"no added light");
 File.WriteAllText(Path.Combine(output,"checks.json"),"{\"pass\":true,\"cases\":[\"before\",\"after\"],\"prefabsPerCase\":43,\"placementsPerCase\":1,\"nonblockingColliderPreserved\":true,\"unrelated42MeshesExact\":true,\"ropeAndClothMaterialKindsSeparate\":true,\"newTextureBytes\":0,\"groundedFibreUvExact\":true,\"readerSourceUnchanged\":true,\"playerExecuted\":false}");
 }catch(Exception e){Debug.LogException(e);File.WriteAllText(Path.Combine(output,"error.txt"),e.ToString());exit=1;}finally{EditorApplication.Exit(exit);}}
}
